 Crew Socks (3-pack), grey / purple / yellow"],["~textured-socks-trio/2","Textured Crew Socks (3-pack), grey / purple / yellow, detail"],["~textured-socks-trio/3","Textured Crew Socks (3-pack), grey / purple / yellow, close-up"]]},{"s":"cuban-chain-gold","n":"Cuban Link Chain","c":"accessories","d":"A delicate gold-toned chain with a Cuban link design, perfect for layering with other necklaces or wearing solo. Can be worn with casual or dressy outfits.","m":"Gold-plated brass. Avoid exposure to water or harsh chemicals, and clean with a soft cloth.","p":5800,"a":3284015,"cn":"Gold tone","hx":"#C9A54C","v":[["45 cm",16],["50 cm",10]],"i":[["~cuban-chain-gold/1","Cuban Link Chain, gold tone"],["~cuban-chain-gold/2","Cuban Link Chain, gold tone, detail"],["~cuban-chain-gold/3","Cuban Link Chain, gold tone, close-up"]]},{"s":"fine-chain-set-gold","n":"Fine Chain Necklace Set","c":"accessories","d":"A delicate chain necklace set in a gold tone finish. Features multiple links and a minimalist design, perfect for layering or wearing solo.","m":"Plated metal. Avoid exposure to water or harsh chemicals. Store in a cool, dry place.","p":7300,"a":3369921,"cn":"Gold tone","hx":"#C9A54C","v":[["45 cm",0],["50 cm",14]],"i":[["~fine-chain-set-gold/1","Fine Chain Necklace Set, gold tone"],["~fine-chain-set-gold/2","Fine Chain Necklace Set, gold tone, detail"],["~fine-chain-set-gold/3","Fine Chain Necklace Set, gold tone, close-up"]]}]'::jsonb)),
prod as (
  insert into public.products (slug, name, category_id, description, material_care, price_cents, status, drop_label, created_at)
  select r->>'s', r->>'n', c.id, r->>'d', r->>'m', (r->>'p')::int, 'published', 'Drop 07',
         now() - make_interval(secs => (r->>'a')::int)
  from src join public.categories c on c.slug = r->>'c'
  on conflict (slug) do update set name = excluded.name, category_id = excluded.category_id,
    description = excluded.description, material_care = excluded.material_care,
    price_cents = excluded.price_cents, status = excluded.status, drop_label = excluded.drop_label
  returning id, slug
),
fresh as (
  select prod.id, src.r from prod join src on src.r->>'s' = prod.slug
  where not exists (select 1 from public.product_colors pc where pc.product_id = prod.id)
),
col as (
  insert into public.product_colors (product_id, name, hex, sort)
  select id, r->>'cn', r->>'hx', 0 from fresh
  returning id, product_id
),
var as (
  insert into public.product_variants (product_id, color_id, size, stock)
  select f.id, col.id, v->>0, (v->>1)::int
  from fresh f join col on col.product_id = f.id, jsonb_array_elements(f.r->'v') v
  returning 1
)
insert into public.product_images (product_id, path, alt, sort)
select f.id, replace(im.value->>0, '~', 'static/catalog/'), im.value->>1, (im.ordinality - 1)::smallint
from fresh f, jsonb_array_elements(f.r->'i') with ordinality im;
